C++ if statements are similar to Java:

```cpp
#include <iostream>
using namespace std;

int main() {
    int age;
    cout << "Enter your age: ";
    cin >> age;

    if (age >= 18) {
        cout << "You are an adult!" << endl;
        cout << "You can vote!" << endl;
    }
    else if (age >= 13) {
        cout << "You are a teenager!" << endl;
    }
    else {
        cout << "You are a child!" << endl;
    }

    // Multiple conditions
    if (age >= 16 && age < 18) {
        cout << "You can drive but can't vote yet." << endl;
    }

    return 0;
}
```

