C++ has powerful loop constructs:

```cpp
#include <iostream>
using namespace std;

int main() {
    // For loop - similar to Java
    cout << "Counting to 5:" << endl;
    for (int i = 1; i <= 5; i++) {
        cout << "Count: " << i << endl;
    }

    // While loop
    cout << "\nCountdown:" << endl;
    int countdown = 5;
    while (countdown > 0) {
        cout << countdown << endl;
        countdown--;
    }
    cout << "Blast off!" << endl;

    // Range-based for loop (C++11 and later)
    int numbers[] = {1, 2, 3, 4, 5};
    cout << "\nNumbers: ";
    for (int num : numbers) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}
```

